69:         void startLoop(){ if(loop==null){running=true;loop=new Thread(this,"BarakelLoop");loop.start();} }
70:         void stopLoop(){running=false;if(loop!=null){try{loop.join(500);}catch(Exception ignored){}loop=null;} }
