73:         @Override public void run(){
74:             lastFrame=System.nanoTime();
75:             while(running){
76:                 long now=System.nanoTime(); float dt=Math.min(.04f,(now-lastFrame)/1_000_000_000f); lastFrame=now;
77:                 update(dt); Canvas c=null;
