83:         void begin(){ mode=1;wave=1;score=0;kills=0;hp=100;mana=100;px=480;py=280;dx=0;dy=-1;enemies.clear();bolts.clear();spawnWave(); }
84:         void spawnWave(){ int amount=wave==1?5:wave==2?7:wave==3?8:0; for(int i=0;i<amount;i++){float a=(float)(i*Math.PI*2/amount)+.3f;float r=240+random.nextInt(35);int kind=wave>=3&&i==0?2:random.nextInt(4)==0?1:0;enemies.add(new Enemy(clamp(px+(float)Math.cos(a)*r,40,920),clamp(py+(float)Math.sin(a)*r,55,485),kind));} if(wave==4) enemies.add(new Enemy(735,270,2)); }
85:         float clamp(float v,float lo,float hi){return Math.max(lo,Math.min(hi,v));}
86:         void update(float dt){
87:             elapsed+=dt; attackCd=Math.max(0,attackCd-dt);magicCd=Math.max(0,magicCd-dt);invuln=Math.max(0,invuln-dt);damageFlash=Math.max(0,damageFlash-dt);
88:             if(mode!=1)return;
89:             float mx=axisX+(moveRight?1:0)-(moveLeft?1:0)+stickX;
90:             float my=axisY+(moveDown?1:0)-(moveUp?1:0)+stickY;
91:             float len=(float)Math.hypot(mx,my); if(len>1){mx/=len;my/=len;}
92:             if(len>.12f){px+=mx*178*dt;py+=my*178*dt;dx=mx;dy=my;}
93:             px=clamp(px,36,924);py=clamp(py,64,480);
94:             if(attack&&attackCd<=0) melee();
95:             if(cast&&magicCd<=0) castMagic();
96:             for(int i=bolts.size()-1;i>=0;i--){Bolt b=bolts.get(i);b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;boolean hit=false;
97:                 for(int j=enemies.size()-1;j>=0;j--){Enemy e=enemies.get(j);if(distance(b.x,b.y,e.x,e.y)<25){e.hp-=2;e.hitFlash=.14f;hit=true;if(e.hp<=0) defeat(j);break;}}
98:                 if(hit||b.life<=0||b.x<0||b.x>W||b.y<0||b.y>H)bolts.remove(i);
99:             }
100:             for(int i=enemies.size()-1;i>=0;i--){Enemy e=enemies.get(i);e.hitFlash=Math.max(0,e.hitFlash-dt);float vx=px-e.x,vy=py-e.y,d=(float)Math.hypot(vx,vy);if(d>30){e.x+=vx/d*e.speed*dt;e.y+=vy/d*e.speed*dt;}else{e.attackTimer-=dt;if(e.attackTimer<=0){e.attackTimer=.9f;if(invuln<=0){hp-=e.kind==2?13:8;invuln=.65f;damageFlash=.2f;if(hp<=0){hp=0;mode=3;}}}}
101:             }
