103:             mana=Math.min(100,mana+2.5f*dt);
104:         }
105:         void melee(){attackCd=.34f;float reach=86;for(int i=enemies.size()-1;i>=0;i--){Enemy e=enemies.get(i);float vx=e.x-px,vy=e.y-py,d=(float)Math.hypot(vx,vy);if(d<reach&&((vx*dx+vy*dy)/Math.max(1,d))>.12f){e.hp-=2;e.hitFlash=.16f;if(e.hp<=0)defeat(i);}}}
106:         void castMagic(){if(mana<30){magicCd=.25f;return;}mana-=30;magicCd=.38f;float d=(float)Math.hypot(dx,dy);if(d<.1f){dx=0;dy=-1;d=1;}bolts.add(new Bolt(px+dx*22,py+dy*22,dx/d*340,dy/d*340));}
107:         void defeat(int index){enemies.remove(index);score+=100+wave*25;kills++;}
108:         float distance(float x,float y,float a,float b){return (float)Math.hypot(x-a,y-b);}
109:         @Override public boolean onTouchEvent(MotionEvent e){
110:             float x=(e.getX()-renderOffsetX)/renderScale,y=(e.getY()-renderOffsetY)/renderScale;int action=e.getActionMasked(),idx=e.getActionIndex(),id=e.getPointerId(idx);
111:             if(action==MotionEvent.ACTION_DOWN||action==MotionEvent.ACTION_POINTER_DOWN){
112:                 if(mode!=1){begin();return true;}
113:                 if(x<260&&y>300){movePointer=id;moveOriginX=105;moveOriginY=440;setStick(x,y);}
114:                 else if(x>805&&y>320){attackPointer=id;attack=true;}
115:                 else if(x>660&&y>320){castPointer=id;cast=true;}
116:                 else if(x>W-80&&y<80){mode=0;}
117:                 return true;
