119:             if(action==MotionEvent.ACTION_MOVE){for(int i=0;i<e.getPointerCount();i++){int pid=e.getPointerId(i);float tx=(e.getX(i)-renderOffsetX)/renderScale,ty=(e.getY(i)-renderOffsetY)/renderScale;if(pid==movePointer)setStick(tx,ty);}return true;}
120:             if(action==MotionEvent.ACTION_UP||action==MotionEvent.ACTION_POINTER_UP||action==MotionEvent.ACTION_CANCEL){int pid=e.getPointerId(idx);if(pid==movePointer){movePointer=-1;stickX=stickY=0;thumbX=moveOriginX;thumbY=moveOriginY;}if(pid==attackPointer){attackPointer=-1;attack=false;}if(pid==castPointer){castPointer=-1;cast=false;}return true;}
121:             return true;
122:         }
123:         void setStick(float x,float y){float vx=x-moveOriginX,vy=y-moveOriginY,d=(float)Math.hypot(vx,vy);if(d>62){vx=vx/d*62;vy=vy/d*62;}thumbX=moveOriginX+vx;thumbY=moveOriginY+vy;stickX=vx/62;stickY=vy/62;}
